protected function resolvePrimitive(ReflectionParameter $parameter)
{
    $configResolution = Util::tryResolveConfigAttribute($parameter, $this);
    $hasConfigAttribute = $configResolution['is_config'] === true;
    $configValueIsNull = $configResolution['is_null'] === true;
    $configValue = $configResolution['value'];
    $resolvedConfigValue = $configValue;

