input.oldString:
    public static function getContextualAttributeFromDependency($dependency)
    {
        return $dependency->getAttributes(ContextualAttribute::class, ReflectionAttribute::IS_INSTANCEOF)[0] ?? null;
    }

    /**
     * Resolve a Config contextual attribute on a primitive parameter, if present.
     *
     * @param  \ReflectionParameter  $parameter
     * @param  \Illuminate\Contracts\Container\Container  $container
     * @return array{is_config: bool, is_null: bool, value: mixed}
     */
    public static function tryResolveConfigAttribute($parameter, ContainerContract $container)
    {
        $attribute = static::getContextualAttributeFromDependency($parameter);

        if ($attribute === null) {
            return [
                'is_config' => false,
                'is_null' => true,
                'value' => null,
            ];
        }

        $instance = $attribute->newInstance();

        if (! $instance instanceof Config) {
            return [
                'is_config' => false,
                'is_null' => true,
                'value' => null,
            ];
        }

        $value = Config::resolve($instance, $container);

        return [
            'is_config' => true,
            'is_null' => $value === null,
            'value' => $value,
        ];
    }
}

